"""Record the coordinator's reconciled decisions after the three sealed audits."""
import hashlib
import json
from pathlib import Path

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))

validation = read('curriculum/proposals/unit16/validation.json')
assert validation['status'] in ['pass', 'passed', 'accepted', 'ready_for_contract']
assert not validation['issues']
assert all(t['dependency_status'] == 'closed' for t in read('curriculum/proposals/unit16/task-plan.json')['tasks'])
checked = []
for path, fields in [
    ('sources/audits/unit16-grammar/manifest.json', ['files', 'external_reconciled_inputs']),
    ('sources/audits/unit16-source/artifact-manifest.json', ['artifacts'])
]:
    manifest = read(path)
    for field in fields:
        for row in manifest[field]:
            assert hashlib.sha256(Path(row['path']).read_bytes()).hexdigest() == row['sha256'], row['path']
            checked.append(row['path'])

record = {'schema_version': 1, 'chapter_id': 'ch16', 'status': 'accepted_for_contract', 'coordinator': 'root', 'prior_checkpoint': 'e1d94be968e89ecfc4918ed58d850702e5d0e57e', 'accepted_reports': ['sources/audits/unit16-source/source-audit-report.json', 'sources/audits/unit16-grammar/review-report.json', 'curriculum/proposals/unit16/validation.json'], 'manifest_identities_checked': len(checked), 'primary_inspections': 'sources/audits/unit16-coordinator/primary-inspections.json', 'root_translation_witness': 'sources/audits/unit16-coordinator/source-first-translation.md', 'decisions': ['Assign every one of the 59 exact joint XII,XIII Exercises 32–36 prompts, preserving original hints, number and word-order controls. The canonical crosswalk becomes 515 assigned, 129 deferred and none excluded out of 644.', 'Assign the complete 444-word Gymnasium subsection at Cook168.1–170.16 / PDF184–186, with all54 original notes and59 anchors. Individual line numbers are editorial counts. Neither earlier Apollonius extracts nor the following feast is reassigned.', 'The prior fifteen active contracts and actual registers alone establish teaching. Preserve all2635 fixed prior artifacts, both complete earlier register histories.', 'Accept56 complete explicitly bounded paradigms /564 literal cells:26 nominal systems with356 cells and30 verbal systems with208 cells. Complete morphology does not establish every construction, sense or unassigned mood.', 'Accept76 tasks /179 requested outputs, including17 original tasks and four translated examples. The morphology group has56 outputs:45 single forms, three two-word phrases and eight explanations; do not report56 form cells.', 'Supply difficult phrases and source-only grammar visibly. Ordered model positions distinguish supplied clauses, productive recall and dictionary-form reference identification even when their component forms are familiar.', 'Retain and document C06: Cook34.9 prints reward(āgyltan,113); evidence supports strongIII āgyldan with contracted āgylt. Supply the bounded reward clause and the separately evidenced impending is tō cumanne phrase. Matthew132/PDF142 directly corroborates both; do not create an unrestricted future auxiliary or new full productive reward system.', 'Retain new composition masculine sǣ, prior findan1sgfand, gīeman with genitive, short-e beran and strǣte. Exact source variants remain separate. Teach the narrow dēme gē command condition newly; the earlier explicit exclusion is preserved.', 'Retain both negatives in the supplied cessation clause36.3. In36.6 first lǣs is adverbial accusative, second nominative passive subject. Do not generalize its attracted dative into a dative subject for lufian.', 'The nearu tables retain nearone/nearore/nearora and the complete selected strong/weak system; bēgen/bā is plural with bēgra/bǣm. nętt has zero nominative/accusative plural. Singular-only title/mass selections are bounded senses, not assertions of inherent defectiveness.', 'Source hǣle170.2 retains its actual supplied feminine accusative safety/rescue identity. John forms Johannes/Johannem have primary WS evidence on Matthew114/PDF124, with declared initialI→J only; no Latin paradigm is assumed.', 'Preserve næfde in169.6 and the unresolved reference, awkward geslægene and tentative top. Cook169note10 describes rubbing with ointment without an explicit shoulder or neck noun. Explain the Latin in English; no Latin knowledge is required. Preserve mixed speech and missing closing quotation punctuation with local explanation.', 'The books/hooks, hooked-letter and ōð-ðæt repairs correct our transcription, not Cook. Initial witnesses and explicit amendments are retained. The root initial positive rendering of næfde is preserved with its corrective addendum.', 'Keep cunnan and witan sense contrasts nonexclusive; distinguish perception accusative plus infinitive from finite content clauses, and interpret relative time without automatic backshift. All new independent demands require actual teaching before their first task.', 'Commit this reconciled contract before learner/key prose. A fresh non-author must freeze every actual learner answer in Git before explicit comparison access; a separate fresh reviewer checks every paradigm against primary evidence. Complete exports, every-page non-author inspection and preserved register integration remain mandatory. Unit17 remains undrafted.'], 'unresolved_material_dependencies': [], 'independence_limit': 'Root and the three audit/design agents have current authoring exposure and do not claim fresh blind review. Audit agreement and structural checks do not replace the later independent linguistic and presentation gates.'}
destination = Path('sources/audits/unit16-coordinator/reconciliation.json')
assert not destination.exists(), 'Preserve the initial reconciliation; later changes require amendments.'
destination.write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')
print('Reconciliation accepted; checked', len(checked), 'manifest identities. Contract assembly remains a separate step.')
